package com.saga.be.controller;
import com.saga.be.dto.ai.AiAcademicClassificationResponse; import com.saga.be.entity.ai.AiAcademicClassification; import com.saga.be.entity.enums.*; import com.saga.be.security.SagaUserPrincipal; import com.saga.be.service.ai.*; import com.saga.be.service.projection.ProjectDataAuthorization; import java.util.*; import org.springframework.context.annotation.Profile; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @Profile("!test") @RequestMapping("/api/projects/{projectId}/ai") public class ProjectAiAcademicClassificationController { private final AiAcademicClassificationRepositoryFacade read; private final AiAcademicReviewService reviews; public ProjectAiAcademicClassificationController(AiAcademicClassificationRepositoryFacade r,AiAcademicReviewService v){read=r;reviews=v;} @GetMapping("/tasks/{taskId}/academic-classifications") public List<AiAcademicClassificationResponse> task(@AuthenticationPrincipal SagaUserPrincipal p,@PathVariable UUID projectId,@PathVariable UUID taskId){return read.history(p.getUserId(),projectId,AiArtifactType.TASK,taskId);}@GetMapping("/commits/{id}/academic-classifications") public List<AiAcademicClassificationResponse> commit(@AuthenticationPrincipal SagaUserPrincipal p,@PathVariable UUID projectId,@PathVariable UUID id){return read.history(p.getUserId(),projectId,AiArtifactType.COMMIT,id);}@PostMapping("/academic-classifications/{id}/review") public AiAcademicClassificationResponse review(@AuthenticationPrincipal SagaUserPrincipal p,@PathVariable UUID projectId,@PathVariable UUID id,@RequestBody AiAcademicReviewService.Request request){return read.map(reviews.review(p.getUserId(),projectId,id,request));}}
